properties.query:
let alertWindow = 30m;
let corrWindow = 10m;
let posVelGate = 0.05;
let vertGate = 0.05;
let compassGate = 0.05;
let airspeedGate = 2.0;
let PosVelSignal =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where PosHorizVariance > posVelGate or VelocityVariance > posVelGate
    | project TimeGenerated, UAVId, SignalName = "GNSS_IMU_Variance";
let BaroSignal =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where PosVertVariance > vertGate
    | project TimeGenerated, UAVId, SignalName = "Baro_Variance";
let MagSignal =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where CompassVariance > compassGate
    | project TimeGenerated, UAVId, SignalName = "Mag_Variance";
let AirspeedSignal =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where isnotnull(Airspeed_ms) and isnotnull(Groundspeed_ms) and abs(Airspeed_ms - Groundspeed_ms) > airspeedGate
    | project TimeGenerated, UAVId, SignalName = "Airspeed_Deviation";
union PosVelSignal, BaroSignal, MagSignal, AirspeedSignal
| summarize DistinctSignals = dcount(SignalName), SignalSet = make_set(SignalName), EventCount = count()
    by UAVId, TimeBin = bin(TimeGenerated, corrWindow)
| where DistinctSignals >= 2
| extend TriggerReason = strcat('다중센서_협조_EKF무력화_의심_', tostring(DistinctSignals), '종신호_', tostring(SignalSet))
| extend Severity = 'High'
| project TimeGenerated = TimeBin, UAVId, DistinctSignals, SignalSet, EventCount, TriggerReason, Severity
| order by TimeGenerated desc
